LOT_ORDER = {"0 (démonstrateur)": 0, "1": 1, "2": 2, "3": 3, "4": 4, "Lot distinct": 5, "5": 6}

def slug(t):
    t = unicodedata.normalize("NFKD", t).encode("ascii", "ignore").decode()
    t = re.sub(r"[^a-zA-Z0-9]+", "-", t.lower()).strip("-")
    return t[:60].rstrip("-")

# Un dossier par lot (choix du 2026-10-08) : clé du lot, dossier, titre, but, démonstration de fin
LOTS = [
 ("0 (démonstrateur)", "demonstrateur", "Démonstrateur", "Montrer tôt à la direction générale ce qui se construit, sur données fictives", "Parcours de 5 minutes, en ligne (plan du démonstrateur)"),
 ("1", "lot-1-parcours-certificat", "Lot 1 — Parcours « certificat »", "Un employé complète son profil et dépose ses certificats", "Un employé au dossier complet et un au dossier incomplet, en recette"),
 ("2", "lot-2-traitement-rh", "Lot 2 — Traitement RH", "Les RH valident, pilotent et enregistrent les demandes", "File de validation et tableau de bord sur données fictives"),
 ("3", "lot-3-mise-en-service", "Lot 3 — Mise en service", "Le portail est hébergé, sécurisé et annoncé", "Test complet en recette ; guide RH ; message de lancement ; ouverture aux employés"),
 ("4", "lot-4-carriere-et-engagement", "Lot 4 — Carrière et engagement", "L'employé voit ses postes éligibles et suit ses demandes", "Un employé avec un champ périmé ; un poste publié avec indicateurs vert et orange"),
 ("Lot distinct", "lot-distinct-lettres-et-systeme-rh", "Lot distinct — Lettres et retour au système RH", "Le portail produit les lettres et renvoie les mouvements", "À préciser"),
 ("5", "lot-5-pam", "Lot 5 — PAM", "Le portail devient PAM : nourri par Carrières, connexion par code à usage unique, PER, production sur AWS", "Un employé fictif se connecte par code, voit son dossier Carrières et dépose une pièce, en recette sur AWS"),
]
LOT_DIR = {key: folder for key, folder, *_ in LOTS}

def article(p):
    return "qu'" if p[0].lower() in "aeiouéèêh" else "que "

os.makedirs(ROOT, exist_ok=True)
paths = {}
for (sid, ep, titre, lot, compl, prio, ef, rg, dec, persona, veux, afin, cas, note) in S:
    e = next(x for x in EPICS if x[0] == ep)
    d = os.path.join(ROOT, LOT_DIR[lot])
    os.makedirs(d, exist_ok=True)
    fn = f"US-{sid}-{slug(titre)}.md"
    paths[sid] = f"{LOT_DIR[lot]}/{fn}"
    lot_txt = lot if not compl else f"{lot} ({compl})"
    afin_word = "afin d'" if afin[0].lower() in "aeiouéèêh" and not afin.startswith("que") and not afin.startswith("qu") else ("afin " if afin.startswith(("que", "qu'")) else "afin de ")
    lines = [f"# US-{sid} — {titre}", "", "| | |", "|---|---|",
             f"| **Statut** | {STATUS.get(sid, 'Pas encore')} |",
             f"| **Epic** | {ep} {e[1]} |",
             f"| **Lot** | {lot_txt} |",
             f"| **Priorité** | {prio} |",
             f"| **Exigences** | {ef} |",
             f"| **Règles** | {rg} |",
             f"| **Décisions liées** | {dec} |", "",
             "## Récit", "",
             f"> En tant {article(persona)}**{persona}**, je veux {veux}, **{afin_word}{afin}**.", "",
             "## Pourquoi", "", e[3], "",
             "## Critères d'acceptation", ""]
    for i, c in enumerate(cas, 1):
        lines.append(f"- **CA-{i:02d}** {c}")
    if note:
        lines += ["", "## Notes", "", note]
    box = "[x]" if STATUS.get(sid) == "Fait" else "[ ]"
    lines += ["", "## Definition of Done", "",
              f"- {box} Chaque critère d'acceptation est couvert par un test vert",
              f"- {box} Écran vérifié sur téléphone (390 px) et sur ordinateur (1280 px), s'il y a un écran",
              f"- {box} Données fictives uniquement ; aucun salaire, aucune colonne exclue dans l'API ni les journaux",
              f"- {box} Statut mis à jour ici et dans `../README.md`", ""]
    io.open(os.path.join(d, fn), "w", encoding="utf-8").write("\n".join(lines))

# README de chaque lot : ses stories, groupées par epic
for key, folder, title, goal, demo in LOTS:
    rows = [x for x in S if x[3] == key]
    L = [f"# {title}", "", f"**But :** {goal}.", "", f"**Démonstration de fin :** {demo}.", "",
         f"{len(rows)} stories, groupées par epic. Statuts et enchaînements : [index](../README.md).", ""]
    for code, name, goal_e, why, lots in EPICS:
        group = sorted([x for x in rows if x[1] == code], key=lambda x: x[0])
        if not group: continue
        L += [f"## {code} {name}", "", goal_e, "",
              "| Story | Titre | Priorité | Complément plus tard | Statut |", "|---|---|---|---|---|"]
        for x in group:
            L.append(f"| [US-{x[0]}]({os.path.basename(paths[x[0]])}) | {x[2]} | {x[5]} | {x[4] or '—'} | {STATUS.get(x[0], 'Pas encore')} |")
        L.append("")
    io.open(os.path.join(ROOT, folder, "README.md"), "w", encoding="utf-8").write("\n".join(L))

# Index + plan par lots
I = ["# Epics et user stories de la refonte", "",
     "| | |", "|---|---|",
     "| **Version** | 0.1, 2026-10-07 — première rédaction, à relire avec les maquettes puis à valider par M. Hilaire |",
     "| **Source** | `../cahier-des-charges.md` (exigences EF, ENF), `../tableau-unique-des-regles.md` (RG), `../decisions-a-valider.md` (D) |",
     "| **Numérotation** | Une story porte le numéro de son epic, comme les exigences : US-301 = 1re story de l'epic D3 (EF-301…). Elle est **indépendante** des US-01 → US-35 du MVP et de la V2, retirées de la branche `v2` le 2026-10-08 (historique git, branche `main`) |", "| **Statuts** | Cet index est la source de vérité des statuts ; le fichier de chaque story et `agent.md` §0 les reprennent |", "",
     f"{len(EPICS)} epics, {len(S)} user stories. Chaque fichier de story contient le récit, le pourquoi, les critères d'acceptation et la Definition of Done.", "",
     "## Plan par lots", "",
     "Une story appartient au lot où elle est livrée ; quand un complément arrive plus tard, il est indiqué entre parenthèses.", ""]
for key, folder, title, goal, demo in LOTS:
    rows = sorted([s for s in S if s[3] == key], key=lambda s: s[0])
    if not rows: continue
    I += [f"### [{title}]({folder}/README.md)", "", f"**But :** {goal}. **Démonstration de fin :** {demo}.", "",
          "| Story | Epic | Titre | Priorité | Complément plus tard | Statut |", "|---|---|---|---|---|---|"]
    for s in rows:
        I.append(f"| [US-{s[0]}]({paths[s[0]]}) | {s[1]} | {s[2]} | {s[5]} | {s[4] or '—'} | {STATUS.get(s[0], 'Pas encore')} |")
    I.append("")
I += ["### Enchaînements à respecter", "",
      "| Avant | Après | Pourquoi |", "|---|---|---|",
      "| Référentiel validé (US-501) | Lot 1 en recette | L'employé voit les libellés officiels |",
      "| Dépôt (US-301) | Validation (US-401, US-402) | Rien à valider sans dépôt |",
      "| Certificats validés, mouvements contrôlés (lot 2) | Éligibilité (US-801) | L'éligibilité ne compte que les données validées |",
      "| Hébergement sécurisé (US-002) | Données réelles, ouverture aux employés | Aucune donnée réelle hors production sécurisée |",
      "| Socle déployable (US-001) | Démonstrateur, puis chaque lot en recette | Chaque story se montre en ligne dès qu'elle est finie |", "",
      "### Le démonstrateur pioche dans plusieurs lots", "",
      "Parcours du démonstrateur (`../../9-demonstrateur/plan-demonstrateur.md`) : US-001 → US-101, US-201, US-202, US-301 (lot 1) → US-401, US-402 (lot 2) → US-601 (lot 2) → US-901 (lot 2) → US-801 (lot 4). Une story montrée au démonstrateur garde son statut « Pas encore » tant que sa Definition of Done n'est pas cochée.", "",
      "## Epics", "", "Un epic regroupe les stories d'un même bloc fonctionnel, souvent sur plusieurs lots ; chaque story indique son epic dans son en-tête.", "",
      "| Epic | Objectif | Pourquoi | Stories |", "|---|---|---|---|"]
for (code, name, goal, why, lots) in EPICS:
    ids = ", ".join(f"[US-{s[0]}]({paths[s[0]]})" for s in sorted([s for s in S if s[1] == code], key=lambda s: s[0]))
    I.append(f"| {code} {name} | {goal} | {why} | {ids} |")
I += ["", "## Statuts", "", "| Statut | Signification |", "|---|---|",
      "| **Pas encore** | Aucun code écrit |", "| **En cours** | Commencée |",
      "| **Fait** | Tous les critères d'acceptation couverts par des tests verts, Definition of Done cochée |", ""]
io.open(os.path.join(ROOT, "README.md"), "w", encoding="utf-8").write("\n".join(I))
print(len(EPICS), "epics", len(S), "stories")
for key, folder, *_ in LOTS:
    print(folder, [s[0] for s in S if s[3] == key])
